CREATE TABLE IF NOT EXISTS security_storage_counts (name TEXT PRIMARY KEY, rows INTEGER NOT NULL CHECK(rows>=0));
INSERT OR IGNORE INTO security_storage_counts(name,rows) SELECT 'parse_jobs',COUNT(*) FROM parse_jobs;
DROP TRIGGER IF EXISTS security_cap_parse_jobs;
CREATE TRIGGER security_cap_parse_jobs BEFORE INSERT ON parse_jobs WHEN NOT EXISTS(SELECT 1 FROM parse_jobs WHERE id=NEW.id) AND (SELECT rows FROM security_storage_counts WHERE name='parse_jobs')>=100000 BEGIN SELECT RAISE(ABORT,'technical storage limit reached'); END;
CREATE TRIGGER security_count_add_parse_jobs AFTER INSERT ON parse_jobs BEGIN UPDATE security_storage_counts SET rows=rows+1 WHERE name='parse_jobs'; END;
CREATE TRIGGER security_count_remove_parse_jobs AFTER DELETE ON parse_jobs BEGIN UPDATE security_storage_counts SET rows=rows-1 WHERE name='parse_jobs'; END;
